+    document: {
+      createElement(tagName) {
+        return {
+          tagName,
+          style: {},
+          children: [],
+          appendChild(child) {
+            this.children.push(child);
+          },
+        };
+      },
+    },
+  };
+  vm.runInNewContext(
+    `${gameSource.slice(start, end)}; result = appendPlayerChoiceContent`,
+    context,
+  );
+  return context.result;
